+// Sales from the till: each dish sold uses one recipe portion per qty.
+// A file of sales is applied all or nothing.
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+import { getItem, onHand } from "./items.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/**
+ * Books sales lines { row, ticket, soldAt, dishId, qty }. Tickets already
+ * imported are skipped. Throws bad_request naming the row when an item runs
+ * out, and then changes nothing. Returns { tickets, dishes } imported.
+ */
+export function importSalesLines(store, lines) {
+  store.data.sales ??= [];
+  const known = new Set(store.data.sales.map((s) => s.ticket));
+  const fresh = lines.filter((l) => !known.has(l.ticket));
+  const left = new Map();
+  const plan = fresh.map((l) => {
+    const needs = scaled(getRecipe(store, getDish(store, l.dishId).recipeId), l.qty).filter((n) => n.qty > 0);
+    for (const n of needs) {
+      const item = getItem(store, n.itemId);
+      const have = left.get(n.itemId) ?? onHand(store, n.itemId);
+      if (have < n.qty)
+        throw new AppError("bad_request", { reason: `row ${l.row}: only ${round3(have)} ${item.unit} of ${item.name} left` });
+      left.set(n.itemId, round3(have - n.qty));
+    }
+    return { l, needs };
+  });
+  for (const { l, needs } of plan) {
+    for (const n of needs) consume(store, n.itemId, n.qty, { at: l.soldAt, ref: `sale:${l.ticket}` });
+    store.data.sales.push({ ticket: l.ticket, soldAt: l.soldAt, dishId: l.dishId, qty: l.qty });
+  }
+  return {
+    tickets: new Set(fresh.map((l) => l.ticket)).size,
+    dishes: fresh.reduce((s, l) => s + l.qty, 0),
+  };
+}
+
+/**
+ * Theoretical use (from sales) against actual use (consume movements) per
+ * item between two days, inclusive; items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  const theory = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    const recipe = getRecipe(store, getDish(store, s.dishId).recipeId);
+    for (const n of scaled(recipe, s.qty)) theory.set(n.itemId, (theory.get(n.itemId) ?? 0) + n.qty);
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  return [...new Set([...theory.keys(), ...actual.keys()])]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const t = round3(theory.get(itemId) ?? 0);
+      const a = round3(actual.get(itemId) ?? 0);
+      return { itemId, name: getItem(store, itemId).name, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
